import{_ as t,o,c as a,ag as s}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 0 — Pre-work","description":"","frontmatter":{"source":"setup/README.md"},"headers":[],"relativePath":"setup/index.md","filePath":"setup/index.md"}'),n={name:"setup/index.md"};function r(i,e,h,l,u,c){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="week-0--pre-work" tabindex="-1">Week 0 — Pre-work <a class="header-anchor" href="#week-0--pre-work" aria-label="Permalink to &quot;Week 0 — Pre-work&quot;">​</a></h1><blockquote><p>Get your accounts, privacy settings and browser-based coding environment ready before Studio 1 (your first class: week 1&#39;s Studio A), so that week 1 is about building, not signing up.</p></blockquote><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio 1</strong></td><td>About 60–90 minutes: two accounts, privacy settings, your first AI-built page, a test Codespace, and GitHub Copilot switched on</td></tr><tr><td><strong>Recommended before week 1</strong></td><td>Know Python (or another language) but not JavaScript or the web? Work through <a href="./python-to-javascript.html">From Python to JavaScript</a> (about 60–90 minutes, self-paced)</td></tr><tr><td><strong>During week 1</strong></td><td>About 40 minutes of short tasks: sign the safety contract and take the self-assessment, both on Canvas (the course&#39;s learning management system), and apply for GitHub Education. The AI fluency pre-work (about 3 hours) is split across <a href="./../weeks/01-hello-vibe-coding/homework.html">week 1</a> and <a href="./../weeks/02-ship-your-page/homework.html">week 2</a> homework</td></tr><tr><td><strong>You need</strong></td><td>A laptop with a modern browser, a personal email address, your phone (for two-factor authentication)</td></tr><tr><td><strong>AI use</strong></td><td>🟢 AI on: your first page, and asking a tool where a setting is · 🔴 AI off: the self-assessment</td></tr></tbody></table><p><strong>Canvas</strong> is the course&#39;s learning management system: the website where you submit private work and see your grades. Your instructor will send you the link.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Two things called &quot;Canvas&quot;.</strong> Gemini also has a tool called <strong>Canvas</strong>, which shows a live preview of the code it writes, right in the chat. You&#39;ll use it in step 3 and in weeks 1–4. This page says &quot;Gemini&#39;s Canvas tool&quot; for that one, and plain &quot;Canvas&quot; for the course website.</p></div><p>Work through the steps <strong>in order</strong>. The times are for a first try; a new tool often takes longer the first time, and that&#39;s normal. If a step fails, keep going with the others and ask for help (see <a href="#if-you-get-stuck">If you get stuck</a> at the bottom).</p><h2 id="before-studio-1" tabindex="-1">Before Studio 1 <a class="header-anchor" href="#before-studio-1" aria-label="Permalink to &quot;Before Studio 1&quot;">​</a></h2><h3 id="your-first-hour-the-quick-start" tabindex="-1">Your first hour: the quick start <a class="header-anchor" href="#your-first-hour-the-quick-start" aria-label="Permalink to &quot;Your first hour: the quick start&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Do this</th><th>About</th></tr></thead><tbody><tr><td>1</td><td>Create or confirm a <strong>personal</strong> Google account and a GitHub account, with two-factor authentication on</td><td>15–20 min</td></tr><tr><td>2</td><td>Turn off the &quot;train on my chats&quot; settings</td><td>10 min</td></tr><tr><td>3</td><td><strong>Your first win:</strong> ask a chat assistant for a small web page and watch it run in the preview</td><td>15 min</td></tr><tr><td>4</td><td>Open a test Codespace and see a test page load from it</td><td>15–20 min</td></tr><tr><td>5</td><td>Turn on GitHub Copilot and ask it one question</td><td>10 min</td></tr><tr><td>6</td><td>Skim the safety contract and note your questions for Studio 1</td><td>10 min</td></tr></tbody></table><p>The steps below give the details for each one.</p><p><strong>Check your device first (2 min).</strong> You don&#39;t need a powerful computer. All the coding in this course runs in your browser through <strong>GitHub Codespaces</strong>, a code editor that runs on a computer in the cloud, so you install nothing.</p><ul><li><strong>Any laptop works:</strong> Windows, macOS, Linux or a Chromebook, with an up-to-date browser. Chrome, Edge and Firefox work best with Codespaces.</li><li><strong>A phone or tablet is not enough</strong> for the labs. You need a keyboard and a screen wide enough for an editor and a preview side by side.</li><li><strong>Browser extensions:</strong> strict ad blockers and privacy extensions sometimes break Codespaces. If step 4 fails, try a private window or pause the extension for <code>github.com</code> and <code>github.dev</code>.</li><li>If your internet connection is unreliable, or you use a screen reader or keyboard only, tell your instructor before Studio 1. The <a href="./../resources/accessibility.html">accessibility guide</a> covers the tools used in this course.</li></ul><p>Installing tools on your own laptop is optional and not needed for any week: <a href="./local-setup.html">Optional: set up your own computer</a>.</p><h3 id="step-1--create-or-confirm-your-accounts-1520-min" tabindex="-1">Step 1 — Create or confirm your accounts (15–20 min) <a class="header-anchor" href="#step-1--create-or-confirm-your-accounts-1520-min" aria-label="Permalink to &quot;Step 1 — Create or confirm your accounts (15–20 min)&quot;">​</a></h3><p>Full details, including which accounts you&#39;ll need later in the course: <a href="./accounts.html">Accounts</a>.</p><p><strong>1a. A personal Google account.</strong> You&#39;ll use it for Gemini (weeks 1–6), Google AI Studio (week 6) and a Gemini API key (week 9).</p><ul><li>Use a <strong>personal</strong> account (for example, a Gmail address), not a school or work account. School and work Google accounts often have Gemini or Google AI Studio switched off by an administrator, and your school or employer may be able to see what you do in them.</li><li>If you don&#39;t have one, create one at <a href="https://accounts.google.com/signup" target="_blank" rel="noreferrer">accounts.google.com</a>.</li></ul><p><strong>1b. A GitHub account.</strong> GitHub is where every project in this course is saved and published. Sign up at <a href="https://github.com/signup" target="_blank" rel="noreferrer">github.com/signup</a> and choose the Free plan.</p><ul><li><strong>Pick your username carefully.</strong> It becomes part of your portfolio address: <code>https://[username].github.io</code>. Use something you&#39;d be happy to put on a CV, such as <code>alexkim</code> or <code>alex-kim-dev</code>. Avoid jokes, birth years and your school&#39;s name.</li><li>Turn on <strong>two-factor authentication</strong> (a second check, such as a code from an app on your phone, when you sign in). GitHub requires it for accounts that contribute code. Save the recovery codes in a password manager. <a href="./accounts.html#security-hygiene">How and why</a></li><li>Already have an account from work? If your employer manages it (you sign in through your company), create a separate personal account for this course.</li></ul><p><strong>1c. A second chat assistant (recommended, by week 4).</strong> In week 4 you compare two AI assistants. Create a free <a href="https://chatgpt.com/" target="_blank" rel="noreferrer">ChatGPT</a> account, or a <a href="https://claude.ai/" target="_blank" rel="noreferrer">Claude</a> account if you&#39;re 18 or older. You can do this now or in the first weeks of the course.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Students:</strong> if you have your student email or ID to hand, apply for GitHub Education now too (<a href="#apply-for-github-education-students-10-min-plus-waiting">details</a>). It&#39;s the one week-1 task that benefits from an early start, because verification can take days.</p></div><p>✅ <strong>Checkpoint:</strong> you can sign in to your personal Google account and to GitHub, and GitHub asks for your second factor when you sign in on a new browser.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Some tools in this course are for adults only (18+), and some can&#39;t be used to serve people in the EEA, UK or Switzerland. <a href="./../TOOLS.html">Tool Handout</a> lists the age rules. If either applies to you, tell your instructor <strong>before Studio 1</strong>; your instructor has an adjusted tool list.</p></div><h3 id="step-2--change-your-privacy-settings-10-min" tabindex="-1">Step 2 — Change your privacy settings (10 min) <a class="header-anchor" href="#step-2--change-your-privacy-settings-10-min" aria-label="Permalink to &quot;Step 2 — Change your privacy settings (10 min)&quot;">​</a></h3><p>Most free AI tools use your conversations to train their models unless you switch that off, and some let human reviewers read samples. Change the settings <strong>before</strong> you type anything into them.</p><p>Follow <a href="./privacy-settings.html">Privacy settings</a> for every tool you signed up for in step 1. At a minimum:</p><ul><li><strong>Gemini:</strong> turn off <em>Keep Activity</em>. That&#39;s the course setting. Gemini then won&#39;t keep your chat history, so you copy the prompts that matter as you go: into your own notes in week 1, and into your <code>PROMPTS.md</code> log from week 2 (<a href="./privacy-settings.html#gemini">why</a>).</li><li><strong>ChatGPT / Claude</strong> (if you created them): turn off the &quot;improve the model&quot; setting.</li><li><strong>GitHub Copilot:</strong> turn off use of your data for training (you&#39;ll do this in step 5).</li></ul><p>✅ <strong>Checkpoint:</strong> for each tool you use, you can point to the setting you changed, or you know that the tool has no opt-out and you must never paste personal or secret data into it.</p><h3 id="step-3--your-first-win-a-page-in-a-chat-preview-15-min" tabindex="-1">Step 3 — Your first win: a page in a chat preview (15 min) <a class="header-anchor" href="#step-3--your-first-win-a-page-in-a-chat-preview-15-min" aria-label="Permalink to &quot;Step 3 — Your first win: a page in a chat preview (15 min)&quot;">​</a></h3><p>🟢 <strong>AI on.</strong> This is a taste of week 1: you describe a page, and the AI builds it in front of you.</p><ol><li><p>Open <a href="https://gemini.google.com/" target="_blank" rel="noreferrer">gemini.google.com</a> with your personal Google account.</p></li><li><p>Start a new chat and choose Gemini&#39;s <strong>Canvas</strong> tool (look under <strong>Tools</strong> or the <strong>+</strong> button; menus move).</p></li><li><p>Paste this prompt and send it:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: A one-file web page that says &quot;Hello from Building Apps with AI&quot; in big letters, with a button that changes the background to a random color.</span></span>
<span class="line"><span>Context: I&#39;m new to building web pages. I&#39;ll look at the page in the preview.</span></span>
<span class="line"><span>Constraints: One HTML file with the CSS and JavaScript inside it. No libraries.</span></span>
<span class="line"><span>Done when: The preview shows the heading and the button, and each click changes the background color.</span></span></code></pre></div></li><li><p>Wait for the preview to appear next to the chat, then click the button a few times.</p></li><li><p>Ask for one change, for example <code>Make the button bigger and give it rounded corners.</code>, and watch the preview update.</p></li></ol><p>✅ <strong>Checkpoint:</strong> the page appears in the preview, and the button changes the background color. You&#39;ve just built a working web page with AI.</p><p>There&#39;s nothing to save today. With Keep Activity off, the chat won&#39;t stay in your history, and that&#39;s fine.</p><p><strong>No Canvas tool in Gemini, or no preview?</strong> Use another chat assistant with a live preview from <a href="./../TOOLS.html">Tool Handout</a> (Claude&#39;s Artifacts, if you&#39;re 18 or older). ChatGPT shows the code but doesn&#39;t run it.</p><h3 id="step-4--open-a-test-codespace-1520-min" tabindex="-1">Step 4 — Open a test Codespace (15–20 min) <a class="header-anchor" href="#step-4--open-a-test-codespace-1520-min" aria-label="Permalink to &quot;Step 4 — Open a test Codespace (15–20 min)&quot;">​</a></h3><p>This is a dress rehearsal for the weeks when you work in Codespaces. Doing it now means any problem shows up early.</p><ol><li><p>On GitHub, create a new <strong>private</strong> repository called <code>vc101-practice</code>, and tick <strong>Add a README file</strong>. (<a href="./github-basics.html#create-a-repository">Step-by-step instructions</a>)</p></li><li><p>On the repository page, click the green <strong>Code</strong> button → <strong>Codespaces</strong> tab → <strong>Create codespace on main</strong>. A new tab opens. The first start takes a minute or two.</p></li><li><p>When you see the editor, open the terminal (the panel at the bottom; if it&#39;s hidden, press <code>Ctrl+\`</code>). Type these two commands, pressing Enter after each:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;h1&gt;Hello from my Codespace&lt;/h1&gt;&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.html</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http.server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span></span></code></pre></div></li><li><p>A message appears saying your application on port 8000 is available. Click <strong>Open in Browser</strong>.</p><p>✅ <strong>Checkpoint:</strong> a new tab shows &quot;Hello from my Codespace&quot; in large text.</p></li><li><p>Go back to the Codespace tab. Click in the terminal and press <code>Ctrl+C</code> to stop the server.</p></li><li><p>Leave the codespace open for step 5.</p></li></ol><p>More on what you just did, and what to do when something goes wrong: <a href="./codespaces.html">GitHub Codespaces</a>.</p><h3 id="step-5--turn-on-github-copilot-10-min" tabindex="-1">Step 5 — Turn on GitHub Copilot (10 min) <a class="header-anchor" href="#step-5--turn-on-github-copilot-10-min" aria-label="Permalink to &quot;Step 5 — Turn on GitHub Copilot (10 min)&quot;">​</a></h3><p>GitHub Copilot is the AI assistant built into the editor. You&#39;ll use it in the editor weeks (from week 7), and as an agent from week 11.</p><ol><li><p>Go to GitHub&#39;s Copilot settings page: <a href="https://github.com/settings/copilot" target="_blank" rel="noreferrer">github.com/settings/copilot</a>. If you&#39;re offered <strong>Copilot Free</strong>, turn it on. If your GitHub Education application has been approved, you may see <strong>Copilot Student</strong> instead; use that.</p></li><li><p>On the same page (or its <strong>Features</strong> tab), turn off the setting that lets GitHub use your data for AI model training. (<a href="./privacy-settings.html#github-copilot">Details</a>)</p></li><li><p>Back in your <code>vc101-practice</code> codespace (reopen it from <a href="https://github.com/codespaces" target="_blank" rel="noreferrer">github.com/codespaces</a> if you closed it), open the Chat view (the chat icon at the top of the window) and, in <strong>Ask</strong> mode, type:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>In one short paragraph, explain what the command &quot;python3 -m http.server 8000&quot; does.</span></span></code></pre></div><p>✅ <strong>Checkpoint:</strong> Copilot answers in the chat panel.</p></li><li><p><strong>Stop the codespace</strong> so it doesn&#39;t use up your free monthly hours: open <a href="https://github.com/codespaces" target="_blank" rel="noreferrer">github.com/codespaces</a>, click the <strong>…</strong> next to your codespace, and choose <strong>Stop codespace</strong>.</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Menus move. If you can&#39;t find a button or setting named here, ask the assistant where it is, or check <a href="./codespaces.html#turn-on-github-copilot-free">GitHub Codespaces: Turn on GitHub Copilot Free</a>.</p></div><p>Copilot Free has a monthly allowance. You don&#39;t need to worry about it yet; <a href="./../TOOLS.html#credits-budget-for-the-course">Tool Handout: Credits budget for the course</a> explains how to plan it for weeks 7–16. The allowance resets monthly, so the course spans several resets.</p><h3 id="step-6--skim-the-safety-contract-10-min" tabindex="-1">Step 6 — Skim the safety contract (10 min) <a class="header-anchor" href="#step-6--skim-the-safety-contract-10-min" aria-label="Permalink to &quot;Step 6 — Skim the safety contract (10 min)&quot;">​</a></h3><p>Skim the <a href="./safety-contract.html">safety contract</a>. It has nine rules and three project rules, and each rule starts with a one-line version in plain English and the week it&#39;s taught. Don&#39;t worry about the technical words yet; Studio 1 introduces the contract, and you sign it on Canvas during week 1. Write down anything that worries you or doesn&#39;t make sense, and bring it to Studio 1.</p><p>✅ <strong>Checkpoint:</strong> you can say, in your own words, why you should never paste an API key into a chat assistant.</p><h3 id="youre-ready-for-studio-1-when" tabindex="-1">You&#39;re ready for Studio 1 when <a class="header-anchor" href="#youre-ready-for-studio-1-when" aria-label="Permalink to &quot;You&#39;re ready for Studio 1 when&quot;">​</a></h3><ul><li>☐ I can sign in to my <strong>personal</strong> Google account and open Gemini.</li><li>☐ I have a GitHub account with a professional username, two-factor authentication is on, and my recovery codes are saved.</li><li>☐ I changed the privacy settings in every AI tool I signed up for, and Gemini&#39;s Keep Activity is off.</li><li>☐ I built a small page in a chat preview and changed it once.</li><li>☐ I opened a Codespace, ran a command in its terminal, saw my page in the browser, and <strong>stopped</strong> the codespace.</li><li>☐ GitHub Copilot answers me in the Codespace chat, and its training setting is off.</li><li>☐ I skimmed the safety contract and wrote down my questions.</li><li>☐ I know where to find <a href="./../TOOLS.html">Tool Handout</a> (current tools and limits) and <a href="./../resources/troubleshooting.html">troubleshooting</a>.</li></ul><h2 id="recommended-before-week-1-from-python-to-javascript" tabindex="-1">Recommended before week 1: From Python to JavaScript <a class="header-anchor" href="#recommended-before-week-1-from-python-to-javascript" aria-label="Permalink to &quot;Recommended before week 1: From Python to JavaScript&quot;">​</a></h2><p>This course expects you to have taken one programming course, and for most students that was Python. Everything you build here runs in a web browser, so the code is <strong>JavaScript</strong>, the language browsers run, inside web pages made of HTML and CSS. The ideas carry over (variables, loops, functions, lists), but the spelling and a few rules don&#39;t.</p><p>If JavaScript and web pages are new to you, work through <a href="./python-to-javascript.html">From Python to JavaScript</a> before week 1, or during it at the latest. It&#39;s self-paced, takes about 60–90 minutes, and puts short Python and JavaScript examples side by side. It isn&#39;t part of the first-hour quick start above, and it isn&#39;t graded. Already write JavaScript? Do its 10-minute self-check at the end, and skip the rest if it&#39;s easy.</p><h2 id="during-week-1" tabindex="-1">During week 1 <a class="header-anchor" href="#during-week-1" aria-label="Permalink to &quot;During week 1&quot;">​</a></h2><p>About 40 minutes, plus waiting time for GitHub Education. Unless your instructor sets another date on Canvas, these are due before week 2&#39;s Studio A (default 11:59 pm the night before).</p><h3 id="sign-the-safety-contract-on-canvas-15-min" tabindex="-1">Sign the safety contract on Canvas (15 min) <a class="header-anchor" href="#sign-the-safety-contract-on-canvas-15-min" aria-label="Permalink to &quot;Sign the safety contract on Canvas (15 min)&quot;">​</a></h3><p>Read the full <a href="./safety-contract.html">safety contract</a> now that Studio 1 has introduced it. Then open the safety contract assignment on Canvas and type the statement, your name and the date. Ask your instructor about anything that worries you.</p><p>Your signed contract is personal, so it goes on Canvas only. <strong>Don&#39;t commit it to a repository.</strong></p><h3 id="take-the-pre-course-self-assessment-on-canvas-15-min" tabindex="-1">Take the pre-course self-assessment on Canvas (15 min) <a class="header-anchor" href="#take-the-pre-course-self-assessment-on-canvas-15-min" aria-label="Permalink to &quot;Take the pre-course self-assessment on Canvas (15 min)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong> Read the <a href="./../assessment/self-assessment.html">self-assessment</a> and submit your answers on Canvas. It is <strong>not graded</strong>. It tells your instructor where the class is starting from, and in finals week (week 16) you&#39;ll take it again and see how far you&#39;ve come. Take it early in the week, before the course has taught you much. Answer honestly: &quot;I don&#39;t know what that means&quot; is a useful answer.</p><h3 id="apply-for-github-education-students-10-min-plus-waiting" tabindex="-1">Apply for GitHub Education (students, 10 min plus waiting) <a class="header-anchor" href="#apply-for-github-education-students-10-min-plus-waiting" aria-label="Permalink to &quot;Apply for GitHub Education (students, 10 min plus waiting)&quot;">​</a></h3><p>Apply at <a href="https://education.github.com/" target="_blank" rel="noreferrer">education.github.com</a> for the student benefits, which include <strong>GitHub Copilot Student</strong>. You&#39;ll be asked for proof that you&#39;re a student, such as your school email address or a photo of your student ID. Approval can take days, so apply as early in the week as you can. While you wait, use Copilot Free. You&#39;ll want Copilot Student by week 7, when you start using Copilot in the editor.</p><h3 id="ai-fluency-pre-work-weeks-12-homework-about-3-hours" tabindex="-1">AI fluency pre-work (weeks 1–2 homework, about 3 hours) <a class="header-anchor" href="#ai-fluency-pre-work-weeks-12-homework-about-3-hours" aria-label="Permalink to &quot;AI fluency pre-work (weeks 1–2 homework, about 3 hours)&quot;">​</a></h3><p>This is part of your homework, not week 0: a free online course on working with AI that doesn&#39;t depend on any one tool (Anthropic&#39;s &quot;AI Fluency: Framework &amp; Foundations&quot;, or an equivalent your instructor names). You work through the first half in <a href="./../weeks/01-hello-vibe-coding/homework.html">week 1</a> and the rest in <a href="./../weeks/02-ship-your-page/homework.html">week 2</a>, where you also write a short AI-free response on Canvas. The link and the questions are in those homework pages.</p><h3 id="optional-warm-up-about-1-hour" tabindex="-1">Optional: warm up (about 1 hour) <a class="header-anchor" href="#optional-warm-up-about-1-hour" aria-label="Permalink to &quot;Optional: warm up (about 1 hour)&quot;">​</a></h3><p>If you&#39;ve never built anything with AI, try DeepLearning.AI&#39;s free <a href="https://www.deeplearning.ai/courses/build-with-andrew" target="_blank" rel="noreferrer">Build with Andrew</a>. It takes about an hour, assumes no AI background, and works with any chat assistant. Already comfortable building with AI? Skim the <a href="./../resources/glossary.html">glossary</a> and the <a href="./../resources/safe-loop.html">Safe Loop</a> instead.</p><h3 id="done-with-week-0-when" tabindex="-1">Done with week 0 when <a class="header-anchor" href="#done-with-week-0-when" aria-label="Permalink to &quot;Done with week 0 when&quot;">​</a></h3><ul><li>☐ My signed safety contract is on Canvas, and not in any repository.</li><li>☐ My pre-course self-assessment is on Canvas.</li><li>☐ (Students) I have applied for GitHub Education.</li><li>☐ I have a second chat assistant (ChatGPT, or Claude if I&#39;m 18+) ready for week 4.</li><li>☐ (Recommended) I worked through <a href="./python-to-javascript.html">From Python to JavaScript</a>, or I already know some JavaScript.</li></ul><h2 id="if-you-get-stuck" tabindex="-1">If you get stuck <a class="header-anchor" href="#if-you-get-stuck" aria-label="Permalink to &quot;If you get stuck&quot;">​</a></h2><ol><li>Check <a href="./../resources/troubleshooting.html">Troubleshooting</a> and the troubleshooting section of <a href="./codespaces.html#troubleshooting">GitHub Codespaces: Troubleshooting</a>.</li><li>Ask the tool&#39;s own assistant (&quot;Where is the setting that…?&quot;). Never paste a password or recovery code into it.</li><li>Contact your instructor <strong>before</strong> Studio 1 with what you tried and a screenshot of the problem. Account problems are much easier to solve before the first studio than during it.</li></ol><p>Next: <a href="./../weeks/01-hello-vibe-coding/">Week 1 — Hello, Vibe Coding</a>.</p>`,69)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
